<script module lang="ts">
/**
 * The notice that belongs to the application frame and stays until its cause ends (`design/components/banner.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/banner.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import { Icon, agentMember, focusAfterRemoval, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/banner.module.css'
import Button from '../controls/Button.svelte'

export type BannerTone = NonNullable<BannerProps['tone']>

export interface BannerProps {
  /**
   * One `ghost` or `soft` `sm` Button, or one Link: the way out of the condition.
   */
  action?: Snippet
  /**
   * The message, in a sentence or two.
   */
  children: Snippet
  /**
   * The ✕'s accessible name, default `Dismiss`; localized hosts pass their own.
   */
  dismissLabel?: string
  /**
   * Renders the ✕. The app removes the Banner; it passes this only where hiding it is safe.
   */
  onDismiss?: () => void
  tone?: 'info' | 'warning' | 'danger' | 'neutral'
}
</script>

<script lang="ts">
let {
  action,
  children,
  dismissLabel = 'Dismiss',
  onDismiss,
  tone = 'neutral',
}: BannerProps = $props()
const joined = joinSlot(undefined, () => ({}))
const listening = {
  get dismiss() {
    return onDismiss !== undefined
  },
}
const slots = {
  get action() {
    return action
  },
  get default() {
    return children
  },
}
let closeRegion = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = focusAfterRemoval(root)
  release1 = () => {
    ran()
  }
}
watchEffect(effect1, { watch: () => root })
onDestroy(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Banner',
    element: () => root,
    state: () => ({ tone: tone, dismissible: listening.dismiss }),
    actions: {
      dismiss: () =>
        (() => {
          if (!listening.dismiss) throw new Error('This banner has no dismiss control.')
          onDismiss?.()
        })(),
    },
    withholds: () => closeRegion,
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.banner}
    role={tone === 'danger' ? 'alert' : 'status'}
    data-tone={tone}
    data-member="banner"
    >{#if tone !== 'neutral'
      }<span class={styles.glyph}
        ><Icon name={tone === 'danger' ? 'error' : tone === 'warning' ? 'warning' : 'info'}
      /></span
    >{/if
    }<div class={styles.content}
      ><div class={styles.text}>{@render children?.()}</div
      >{#if slots.action}<div class={styles.action}>{@render action?.()}</div>{/if
    }</div
    >{#if listening.dismiss
      }<div bind:this={closeRegion} class={styles.close}
        ><Button
          variant="ghost"
          tone="neutral"
          size="sm"
          iconOnly={true}
          icon="close"
          label={dismissLabel}
          onClick={() => { onDismiss?.() }}
      /></div
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
